def normalize_sql_for_compare(sql_text: str) -> str:
    return re.sub(r"\s+", " ", sql_text).strip().lower()


def manifest_source_dialect_hint(manifest_text: str) -> str:
    match = re.search(r"(?m)^source_dialect:\s*([A-Za-z0-9_+-]+)\s*$", manifest_text)
    return match.group(1) if match else ""


def manifest_source_family_hint(manifest_text: str) -> str:
    match = re.search(r"(?m)^source_family:\s*([A-Za-z0-9_+-]+)\s*$", manifest_text)
    return match.group(1) if match else ""


def normalize_source_dialect_hint(value: str) -> str:
    hint_map = {
        "mysql_like_candidate": "mysql",
        "postgres_like_candidate": "postgres",
        "spark_like_candidate": "spark",
        "mysql": "mysql",
        "postgres": "postgres",
        "spark": "spark",
    }
    return hint_map.get(value, value)


def llm_translate_source_dialect(case_id: str, manifest_text: str = "") -> str:
    source_dialect_hint = normalize_source_dialect_hint(manifest_source_dialect_hint(manifest_text)) if manifest_text else ""
    if source_dialect_hint:
        return source_dialect_hint
    return PORT_TRANSLATE_SOURCE_DIALECT_FALLBACKS.get(case_id, "unknown")


def source_dialect_candidate_order(source_dialect_hint: str, requested: str) -> list[str]:
    default_order = ["mysql", "postgres", "spark"]
    if requested != "auto":
        return [requested]

    hinted = normalize_source_dialect_hint(source_dialect_hint)
    if hinted:
        return [hinted] + [dialect for dialect in default_order if dialect != hinted]
    return list(default_order)


def baseline_inventory_token_cost_class(baseline_id: str) -> str:
    inventory_path = ROOT / "docs" / "_scratch" / "baseline_inventory_boss_requirements.csv"
    if not inventory_path.is_file():
        return "unknown"
    with inventory_path.open(encoding="utf-8", newline="") as f:
        for row in csv.DictReader(f):
            if row.get("baseline_id") == baseline_id:
                return row.get("token_cost_class") or "unknown"
    return "unknown"


